const input = $input.first().json;
const body = input.body || input;
const evidencePack = body.evidence_pack || {};
const snapshot = body.snapshot || {};
const prompt = body.prompt || '';
const templateType = body.template_type || 'generic';

const systemPrompt = `Eres un abogado especializado en due diligence legal.
Genera un informe de tipo "${templateType}" basándote EXCLUSIVAMENTE en las fuentes proporcionadas.

REGLAS DE CITACIÓN:
- CITA cada afirmación factual usando [SRC-XXX]
- NO inventes fuentes
- Si no tienes evidencia, indica "Sin evidencia disponible"

Genera el informe en español con secciones estructuradas.`;

const userPrompt = `${prompt}\n\nEVIDENCE PACK:\n${JSON.stringify(evidencePack, null, 2)}\n\nSNAPSHOT:\n${JSON.stringify(snapshot, null, 2)}`;

return [{
  json: {
    report_id: body.report_id,
    request_id: body.request_id,
    template_type: templateType,
    system_prompt: systemPrompt,
    user_prompt: userPrompt,
    model: 'default'
  }
}];

const harveyResponse = $input.first().json;
const prevData = $('Prepare Harvey Prompt').first().json;

return [{
  json: {
    report_id: prevData.report_id,
    request_id: prevData.request_id,
    template_type: prevData.template_type,
    output: {
      raw_response: harveyResponse.text || harveyResponse.completion || JSON.stringify(harveyResponse),
      model_used: harveyResponse.model || 'harvey-default',
      generated_at: new Date().toISOString()
    },
    status: 'ok'
  }
}];

const input = $input.first().json;
const body = input.body || input;
const snapshot = body.snapshot || {};
const templateType = body.template_type || 'pmo';

// Aggregate data from snapshot for PMO/compliance reports
const summary = {
  report_id: body.report_id,
  request_id: body.request_id,
  template_type: templateType,
  output: {
    raw_response: JSON.stringify(snapshot, null, 2),
    generated_at: new Date().toISOString(),
    data_source: 'snapshot_aggregation',
    note: 'PMO/Compliance reports use data aggregation, no Harvey AI call'
  },
  status: 'ok'
};

return [{ json: summary }];
